import{_ as a,o as e,c as n,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"LLM 基础：Token、上下文、采样与幻觉","description":"理解大语言模型的生成方式、Token 与上下文窗口、采样参数和幻觉边界，为 Prompt、RAG 与 Agent 应用建立基础。","frontmatter":{"title":"LLM 基础：Token、上下文、采样与幻觉","description":"理解大语言模型的生成方式、Token 与上下文窗口、采样参数和幻觉边界，为 Prompt、RAG 与 Agent 应用建立基础。"},"headers":[],"relativePath":"ai/llm-basics.md","filePath":"ai/llm-basics.md","lastUpdated":1792728728000}'),s={name:"ai/llm-basics.md"};function r(l,t,d,i,p,h){return e(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="llm-基础-token、上下文、采样与幻觉" tabindex="-1">LLM 基础：Token、上下文、采样与幻觉 <a class="header-anchor" href="#llm-基础-token、上下文、采样与幻觉" aria-label="Permalink to &quot;LLM 基础：Token、上下文、采样与幻觉&quot;">​</a></h1><p>理解 LLM 的生成方式和限制，才能决定哪些工作交给模型，哪些工作需要检索、计算和业务校验。本文集中解释模型基础；工具调用、会话管理及笔记应用案例已独立到 <a href="/ai/agent-development">AI Agent 开发实战</a>。</p><h2 id="它本质是在预测下一个-token" tabindex="-1">它本质是在预测下一个 Token <a class="header-anchor" href="#它本质是在预测下一个-token" aria-label="Permalink to &quot;它本质是在预测下一个 Token&quot;">​</a></h2><p>模型把输入文本切成 Token，根据已见过的所有 Token，计算词表中每个候选 Token 出现的概率，挑一个接上去，再循环这个过程。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入: &quot;今天天气&quot;</span></span>
<span class="line"><span>  → 计算: 真(0.6) / 很(0.2) / 不(0.1) / ...</span></span>
<span class="line"><span>  → 选取: &quot;真&quot;</span></span>
<span class="line"><span>输入: &quot;今天天气真&quot;</span></span>
<span class="line"><span>  → 计算: 好(0.7) / 不错(0.2) / ...</span></span>
<span class="line"><span>  → 选取: &quot;好&quot;</span></span></code></pre></div><p>这个&quot;逐 Token 生成&quot;带来几个直接后果：</p><ul><li><strong>权重中的知识不是可审计数据库</strong>：模型可以记住知识，但不能仅凭回答证明事实来源、有效期或数据是否最新。</li><li><strong>生成可能变化</strong>：采样设置、服务实现和运行环境都可能影响结果，不能把自然语言输出当作确定性接口。</li><li><strong>精确任务要有外部校验</strong>：计数、计算、检索和业务操作可以交给工具，再用确定性代码验证结果。</li></ul><p>网页检索、文件读取和数据库访问由应用提供。带检索能力的产品可以取得新资料，但这项能力来自模型外围的系统。</p><h2 id="token-与上下文窗口" tabindex="-1">Token 与上下文窗口 <a class="header-anchor" href="#token-与上下文窗口" aria-label="Permalink to &quot;Token 与上下文窗口&quot;">​</a></h2><p>Token 是模型处理文本的单位，具体切分由 tokenizer 决定。汉字、英文、代码和特殊符号的比例会变化，不应用固定字数换算来判断请求是否超限。</p><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>实践影响</th></tr></thead><tbody><tr><td>输入 Token</td><td>指令、历史、工具定义与相关资料</td><td>需要估算、裁剪和记录实际用量</td></tr><tr><td>输出预算</td><td>回复以及模型可能使用的推理预算</td><td>预留容量，具体口径依模型协议</td></tr><tr><td>上下文窗口</td><td>当前请求可容纳的上下文容量</td><td>按模型能力检查，不能只看输入字数</td></tr></tbody></table><p>超限可能被服务端拒绝，也可能由应用先做压缩或裁剪；应用必须说明自己采用了哪种策略。长上下文还需要关注信息位置、相关性和检索质量，不能把整份历史无限追加。</p><h2 id="温度与采样" tabindex="-1">温度与采样 <a class="header-anchor" href="#温度与采样" aria-label="Permalink to &quot;温度与采样&quot;">​</a></h2><p>温度（temperature）等采样参数影响候选 Token 的选择方式。较低温度通常减少随机性，较高温度通常增加多样性，但实际支持范围与行为由提供方和模型决定。</p><p>温度为 0 也不等于结果必然正确或端到端完全可复现。结构化提取还要验证 schema，事实问答还要核对来源，精确计算仍应交给工具。接入思考模型时，应先确认其支持的参数，而不是沿用另一模型的温度配置。</p><h2 id="能力边界-幻觉从哪里来" tabindex="-1">能力边界：幻觉从哪里来 <a class="header-anchor" href="#能力边界-幻觉从哪里来" aria-label="Permalink to &quot;能力边界：幻觉从哪里来&quot;">​</a></h2><p>幻觉（hallucination）指模型生成看起来合理但缺乏依据或与事实不符的内容。模型可能在知识不足、上下文不完整或推断出错时给出自信答案，也可能正确表达不确定性；应用不能只靠语气判断可信度。</p><p>常见的不可靠场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>为什么不可靠</th></tr></thead><tbody><tr><td>具体事实、数字、日期</td><td>知识可能过时或缺少来源，仍需逐项核对</td></tr><tr><td>引用来源、文献</td><td>未取得真实资料时，可能生成不存在的引文</td></tr><tr><td>严格计数与长列表</td><td>自然语言生成不能替代明确的计算与约束检查</td></tr><tr><td>自我描述</td><td>缺少可信运行时信息时，不能靠生成文本确认自身版本</td></tr></tbody></table><p>应对不是&quot;消灭幻觉&quot;，而是把它当作可管理的风险：让模型在有据可查的范围内回答（这就是 RAG 的动机），要求它给出引用，对关键输出做校验，把&quot;可能出错&quot;纳入产品设计而不是假设它一定对。</p><h2 id="上层应用的心智模型" tabindex="-1">上层应用的心智模型 <a class="header-anchor" href="#上层应用的心智模型" aria-label="Permalink to &quot;上层应用的心智模型&quot;">​</a></h2><p>理解了上述基础，再去看 Prompt、Agent、RAG，会清晰很多：</p><ul><li><strong>Prompt 工程</strong>：在固定权重下，用更好的输入引导出更可靠的输出。</li><li><strong>Agent</strong>：让模型通过&quot;调用工具&quot;绕过它不擅长的部分（计算、检索、查询），把可验证的操作交给确定性代码。</li><li><strong>RAG</strong>：检索相关资料并提供可核对的上下文，再验证回答与来源的关系。</li></ul><h2 id="接下来怎样学习" tabindex="-1">接下来怎样学习 <a class="header-anchor" href="#接下来怎样学习" aria-label="Permalink to &quot;接下来怎样学习&quot;">​</a></h2><p>写清输入与输出约束，可以继续读 <a href="/ai/prompt-engineering">Prompt 工程实践</a>；需要依据已有资料回答问题，可以读 <a href="/ai/rag">RAG 检索增强生成</a>。</p><p>如果希望模型根据中间结果调用工具、推进任务，继续读 <a href="/ai/agent-development">AI Agent 开发实战：参考 DeepSeek Harness</a>。它从最小工具开始，完整展开检索笔记、预览采纳与保存结果的业务链路。</p>`,26)])])}const k=a(s,[["render",r]]);export{u as __pageData,k as default};
